"""runtime.stage_services: generated by the graph.py split (P1)."""

from __future__ import annotations

from pathlib import Path
from typing import Iterable

from .. import isa
from ..benchmark import embench
from ..runtime import policy as policy_mod, source_visibility
from ..runtime.artifacts import RunArtifacts
from ..runtime.tools import RepoToolbox
from ..state import CfuDesignState


def _policy(state: CfuDesignState):
    return policy_mod.load_policy(
        Path(state.get("workdir", ".")).resolve(),
        visibility=str(state.get("visibility", "") or ""),
    )


def _artifacts(state: CfuDesignState, policy=None) -> RunArtifacts:
    return RunArtifacts.create(
        Path(state.get("workdir", ".")).resolve(),
        policy or _policy(state),
        out_dir=state.get("out_dir", "agents/generated"),
        run_id=state.get("run_id", ""),
    )


def existing_evidence(
    state: CfuDesignState, candidates: Iterable[tuple[str, str]],
) -> list[tuple[str, str]]:
    """Keep the index entries that already exist under the run's workdir.

    A hand-written index drifts from what the run actually produced: it listed
    ``04_benchmark/manifest.yaml`` for an embench run (the file is
    ``embench.yaml``), an artifact the stage was about to write, and the stage's
    own tool transcript. The model then spent tool calls on files that cannot
    exist yet. Filtering by existence also covers a stage's *repair* round, where
    the previous artifact does exist.
    """
    workdir = Path(state.get("workdir", ".")).resolve()
    kept: list[tuple[str, str]] = []
    for item in candidates:
        path, note = item
        if not path:
            continue
        target = workdir / path
        if target.is_file() or target.is_dir():
            kept.append((path, note))
    return kept


def model_source_text(toolbox: RepoToolbox, path: str, *, limit: int) -> str:
    """Mask a source prefix before bounding a model-facing excerpt.

    Host candidate/verification readers deliberately keep using raw read_text.
    Cap parsing at 2M characters; an incomplete verifier body is masked to EOF.
    """
    read_limit = min(limit, 2_000_000)
    try:
        source = toolbox.resolve(path)
        if isinstance(source, Path):
            read_limit = min(2_000_000, max(limit, source.stat().st_size))
    except (AttributeError, OSError):
        pass  # Missing files and lightweight test doubles retain read semantics.
    text = toolbox.read_text(path, limit=read_limit)
    return source_visibility.mask_file_view(text, path)[:limit]


def _software_targets(state: CfuDesignState, toolbox: RepoToolbox) -> list[tuple[str, str]]:
    """[(writable path, current text)] the software rung may rewrite."""
    spec = state.get("workload_spec", {})
    project = state.get("benchmark_project", {})
    run_root = str(state.get("run_root", "") or "")
    workdir = Path(state.get("workdir", ".")).resolve()
    kind = str(project.get("kind", ""))

    if kind == "embench_benchmark":
        name = str(project.get("benchmark", "") or spec.get("benchmark_name", ""))
        targets = []
        for source in embench.benchmark_source_files(workdir, name) if name else []:
            path = embench.embench_cfu_rel(run_root, name, Path(source).name)
            targets.append((path, toolbox.read_text(path, limit=1_000_000)))
    elif kind == "generated_benchmark":
        source = str(project.get("source_path", ""))
        targets = [(source, toolbox.read_text(source, limit=1_000_000))] if source else []
    elif kind == "instrumented_copy":
        source = str(project.get("source_path", ""))
        targets = [(source, toolbox.read_text(source, limit=1_000_000))] if source else []
    else:
        targets = []
    if run_root and not state.get("isa_contract", True):
        # Ablation (--no-isa-contract): the intrinsics header is agent-authored,
        # so it is an ordinary editable software target alongside the kernel.
        from ..stages.implement.intrinsics import intrinsics_header_path

        header = intrinsics_header_path(state)
        if header and all(path != header for path, _ in targets):
            try:
                text = toolbox.read_text(header, limit=1_000_000)
            except (OSError, policy_mod.PolicyError):
                # Not seeded yet; _write_intrinsics_header seeds it from the
                # intrinsic template before any edit round.
                text = ""
            targets.append((header, text))
    return targets


def _toolbox_for_stage(state: CfuDesignState, stage: str) -> RepoToolbox:
    policy = _policy(state)
    return RepoToolbox(
        Path(state.get("workdir", ".")).resolve(),
        dry_run=state.get("dry_run", False),
        policy=policy,
        stage=stage,
        run_root=state.get("run_root", ""),
        embench_benchmark=str((state.get("benchmark_project") or {}).get("benchmark")
                             or state.get("benchmark_name")
                             or (state.get("workload_spec") or {}).get("benchmark_name") or ""),
        apply_patch=state.get("apply_patch", False),
        enforce_embench_integrity=(
            (state.get("benchmark_project") or {}).get("kind") == "embench_benchmark"
            or (state.get("workload_spec") or {}).get("source_kind") == "embench"
        ),
    )


def benchmark_integrity_problems(toolbox: RepoToolbox) -> list[str]:
    """Production Embench toolboxes enforce this; synthetic tool doubles do not."""
    if getattr(toolbox, "enforce_embench_integrity", False) is not True:
        return []
    return toolbox.benchmark_integrity_problems()


def hardware_integrity_problems(state: CfuDesignState, toolbox: RepoToolbox, *,
                                evidence: dict | None = None, rtl_path: Path | None = None) -> list[str]:
    """Same live-overlay/encoding guard for submit and build, even without conformance."""
    from . import hardware_integrity, instruction_encoding, tools
    from ..stages.implement import intrinsics

    sources = {}
    for path in tools.design_workspace_paths(state.get("run_root", "")).values():
        try:
            sources[path] = toolbox.read_text(path, limit=2_000_000)
        except (OSError, policy_mod.PolicyError) as exc:
            return [f"hardware integrity cannot read {path}: {exc}"]
    spec = state.get("isa_spec") or {}
    problems = hardware_integrity.validate_sources(sources, spec)
    encoding = {"version": instruction_encoding.VERSION, "candidate_hash": intrinsics._hardware_candidate_hash(state, toolbox),
                "isa_hash": instruction_encoding.digest(spec),
                "config": instruction_encoding.configuration(spec)}
    encoding["config_hash"] = instruction_encoding.digest(encoding["config"])
    if state.get("isa_contract", True) and spec.get("commands"):
        encoding["source"] = instruction_encoding.validate_sources(sources, spec)
        problems.extend(encoding["source"]["problems"])
        if rtl_path is not None:
            try:
                rtl_ref = Path(rtl_path)
                if rtl_ref.is_absolute():
                    workdir = Path(getattr(toolbox, "workdir", state.get("workdir", "."))).resolve()
                    rtl_ref = rtl_ref.resolve().relative_to(workdir)
                rtl = toolbox.read_text(rtl_ref.as_posix(), limit=20_000_000)
            except ValueError as exc:
                problems.append(
                    f"hardware integrity cannot read generated RTL {rtl_path}: "
                    f"path is outside the repository workdir ({exc})"
                )
            except (OSError, policy_mod.PolicyError) as exc:
                problems.append(f"hardware integrity cannot read generated RTL {rtl_path}: {exc}")
            else:
                encoding["rtl"] = instruction_encoding.validate_rtl(rtl, spec)
                problems.extend(encoding["rtl"]["problems"])
    else:
        encoding["source"] = {"checked": False, "unchecked": ["no frozen ISA contract: encoding crosscheck disabled"], "problems": []}
    encoding["checked"] = encoding.get("rtl", encoding["source"]).get("checked", False)
    encoding["proof_scope"] = "bounded encoding/enable structure only, not semantic correctness"
    if evidence is not None:
        evidence.update(encoding)
    return problems


def gate_failure_result(state: CfuDesignState, rung: str, reason: str,
                        errors: list[str], *, category: str = "") -> dict:
    """A host check, not a fabricated exit code for an external command.

    Publish an inspectable failure even when all commands succeeded (for example
    result mismatch) or no command ran (fixed-result hardware preflight).
    """
    from . import observations

    text = "\n".join(errors)
    result = {"kind": "host_gate_check", "executed": False, "rung": rung, "returncode": 1,
              "command": f"host gate check: {rung}/{reason}", "reason": reason,
              "terminal_reason": reason, "stderr_tail": text, "stdout_tail": "",
              "log_path": f"{state.get('run_root', '')}/10_validation/{rung}.yaml"}
    item = observations.build_failure_observation(
        rung, result, stderr=text, log_path=result["log_path"],
        workdir=str(state.get("workdir", "")))
    if item is not None:
        item["summary"] = text[:2000]
        item["category"] = category or reason
        signature = observations.failure_signature(
            rung, item["category"], result, text, workdir=str(state.get("workdir", "")))
        item.update(signature=signature,
                    id=f"fail_{rung}_{signature.removeprefix('failure-v1:')[:12]}")
        result["failure_observation"] = item
    return result


def _artifacts_for_stage(state: CfuDesignState, stage: str) -> RunArtifacts:
    return RunArtifacts.create(
        Path(state.get("workdir", ".")).resolve(),
        _policy(state),
        out_dir=state.get("out_dir", "agents/generated"),
        run_id=state.get("run_id", ""),
    )


def _write_profile_artifact(state: CfuDesignState, profile: dict, reason: str) -> None:
    artifacts = _artifacts_for_stage(state, "profile")
    artifacts.write_yaml("profile", "05_profile/result.yaml", dict(profile), status=reason or "produced")


def _write_hotspot_artifact(state: CfuDesignState, hot: str, source: str, candidates: list) -> None:
    artifacts = _artifacts_for_stage(state, "hotspot")
    artifacts.write_yaml(
        "hotspot",
        "06_hotspot/hotspot.yaml",
        {"hot_spot": hot, "source": source, "candidates": candidates},
    )


def _write_analysis_artifact(state: CfuDesignState, analysis: dict) -> None:
    artifacts = _artifacts_for_stage(state, "analysis")
    artifacts.write_yaml("analysis", "07_analysis/workload_analysis.yaml", dict(analysis))


def _write_isa_artifact(state: CfuDesignState, isa_spec: dict, problems: list[str]) -> None:
    artifacts = _artifacts_for_stage(state, "isa")
    artifacts.write_yaml("isa", "08_isa/cfu_isa.yaml", dict(isa_spec), status="invalid" if problems else "produced")
    # Invalid candidates retain YAML and lint evidence without asking the
    # renderer to accept an invalid object or inventing substitute Markdown.
    if not problems:
        markdown = isa.render_isa_markdown(isa_spec)
        artifacts.write_text("isa", "08_isa/cfu_isa.md", markdown, kind="markdown")
    artifacts.write_yaml("isa", "08_isa/validation.yaml", {"status": "invalid" if problems else "valid", "problems": problems})


def _write_hardware_artifact(
    state: CfuDesignState, plan: str, outcome: dict, feedback: str = ""
) -> None:
    artifacts = _artifacts_for_stage(state, "implementation")
    artifacts.write_text("implementation", "09_implementation/hw_plan.md", plan, kind="markdown")
    if feedback:
        artifacts.write_text(
            "implementation",
            "09_implementation/hw_repair_feedback.txt",
            feedback,
            kind="text",
            status="repair",
        )
    if outcome.get("patch"):
        artifacts.write_text("implementation", "09_implementation/hw_patch.diff", outcome["patch"], kind="text")
    artifacts.write_yaml(
        "implementation",
        "09_implementation/hw_changed_files.yaml",
        {
            "design_files": list(outcome.get("files") or []),
            "patch_applied": bool(outcome.get("applied")),
            "proposed": bool(outcome.get("proposed")),
            "repair": bool(feedback),
            # Whether this repair actually reasoned about the injected error log.
            "repair_diagnosis": ("REPAIR_DIAGNOSIS" in plan) if feedback else None,
            "errors": outcome.get("errors") or [],
        },
    )


def _write_software_artifact(
    state: CfuDesignState, plan: str, outcome: dict, errors: list[str], feedback: str = ""
) -> None:
    artifacts = _artifacts_for_stage(state, "implementation")
    artifacts.write_text("implementation", "09_implementation/sw_plan.md", plan, kind="markdown")
    if feedback:
        artifacts.write_text(
            "implementation",
            "09_implementation/sw_repair_feedback.txt",
            feedback,
            kind="text",
            status="repair",
        )
    if outcome.get("patch"):
        artifacts.write_text("implementation", "09_implementation/sw_patch.diff", outcome["patch"], kind="text")
    artifacts.write_yaml(
        "implementation",
        "09_implementation/sw_changed_files.yaml",
        {
            "software_files": list(outcome.get("files") or []),
            "patch_applied": bool(outcome.get("applied")),
            "proposed": bool(outcome.get("proposed")),
            "repair": bool(feedback),
            # Whether this repair actually reasoned about the injected error log.
            "repair_diagnosis": ("REPAIR_DIAGNOSIS" in plan) if feedback else None,
            "errors": errors,
        },
    )


def _write_ladder_artifact(state: CfuDesignState, rung: str, results: list, status: str, reason: str,
                           *, evidence: dict | None = None) -> None:
    artifacts = _artifacts_for_stage(state, "validation")
    artifacts.write_yaml(
        "validation",
        f"10_validation/{rung}.yaml",
        {"rung": rung, "status": status, "reason": reason, "commands": [dict(item) for item in results],
         **(evidence or {})},
    )


def _write_cost_artifact(state: CfuDesignState, results: list, status: str, reason: str) -> None:
    artifacts = _artifacts_for_stage(state, "cost")
    artifacts.write_yaml(
        "cost",
        "11_cost/result.yaml",
        {"status": status, "reason": reason, "commands": [dict(item) for item in results]},
    )


def _report_review_decision(state: CfuDesignState, decision: str, status: str) -> None:
    artifacts = _artifacts_for_stage(state, "review")
    artifacts.write_yaml(
        "review",
        "12_review/decision.yaml",
        {"decision": decision, "status": status, "gates": state.get("gates", {})},
    )


def _profile_reason(state: CfuDesignState) -> str:
    if state.get("dry_run", False):
        return "dry-run"
    if state.get("skip_sim", False):
        return "--skip-sim"
    if not state.get("run_commands", False):
        return "execution-disabled"
    return ""


def _skipped_result(command: str | list[str], state: CfuDesignState, reason: str) -> dict:
    return {
        "command": " ".join(command) if isinstance(command, list) else command,
        "cwd": state.get("workdir", "."),
        "returncode": None,
        "skipped": True,
        "reason": reason,
    }


def _profile_ok(profile: dict) -> bool:
    return profile.get("status") == "profiled"


def base_artifact_root(state: CfuDesignState) -> str:
    root = state.get("out_dir", "agents/generated").strip("/")
    if root == "agents/generated" or root.startswith("agents/generated/"):
        return root
    return "agents/generated"
